import{_ as e,o as d,c as a,ai as o}from"./chunks/framework.Ba-VnP44.js";const E=JSON.parse('{"title":"生产执行管理系统 MES","description":"","frontmatter":{},"headers":[],"relativePath":"instances/industrial/mes.md","filePath":"instances/industrial/mes.md"}'),r={name:"instances/industrial/mes.md"};function i(s,t,c,n,l,p){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="生产执行管理系统-mes" tabindex="-1">生产执行管理系统 MES <a class="header-anchor" href="#生产执行管理系统-mes" aria-label="Permalink to “生产执行管理系统 MES”">​</a></h1><blockquote><p>在 OpenBiz 之上自建的轻量 MES：工单下发 → 报工 → 质检 → 完工，跑通真实生产闭环。 ✅ 已验证 · 所属 <a href="/my-vitepress-site/instances/industrial/">02 工业数字化应用</a> · 模块内优先级 1 · 代码 <code>E:/8.cangku/for-job/openbiz-mes-app</code></p></blockquote><h2 id="功能清单" tabindex="-1">功能清单 <a class="header-anchor" href="#功能清单" aria-label="Permalink to “功能清单”">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>状态</th><th>能做什么</th><th>证据</th></tr></thead><tbody><tr><td>生产工单</td><td>✅</td><td>建单 → 开工 → 报工 → 质检 → 完工全链路，六态状态机</td><td>E2E <code>create→start→report→qc→complete</code> 通过</td></tr><tr><td>报工记录</td><td>✅</td><td>报工时写入生产记录，复用母仓已定义的报工表</td><td>E2E 校验落库可查</td></tr><tr><td>状态机约束</td><td>✅</td><td><code>CREATED→STARTED→REPORTED→QC_PASSED→COMPLETED</code>，含 <code>QC_FAILED</code> 返工与 <code>CANCELLED</code> 分支</td><td>非法流转返回 <code>ILLEGAL_TRANSITION</code></td></tr><tr><td>多租户</td><td>✅</td><td>复用 <code>openbiz-saas-core</code> 的 TenantContext / TenantService / 自动装配</td><td>后端 18082 + 独立库 <code>openbiz_mes</code></td></tr><tr><td>工序流转</td><td>🔧</td><td>工艺路线表母仓已定义，工序交接与工序级流转业务层未实现</td><td>在建</td></tr><tr><td>质检单据</td><td>🔧</td><td>目前只有 QC_PASSED / QC_FAILED 两个状态位，没有独立检验单</td><td>在建</td></tr><tr><td>批次追溯</td><td>📋</td><td>计划中，尚无表与接口</td><td>—</td></tr></tbody></table><h2 id="待完善" tabindex="-1">待完善 <a class="header-anchor" href="#待完善" aria-label="Permalink to “待完善”">​</a></h2><ul><li><strong>报工只到整单级</strong>：不支持按工序分段报工、按人/班次汇总产量与工时</li><li><strong>质检缺实体</strong>：没有检验单、抽样规则、不良代码与返工处置流程，只有状态位</li><li><strong>设备侧未打通</strong>：母仓 <code>iot</code> 域的 <code>mes</code> 插件 <code>startProduction</code> 仍复用 mock 设备指令，未接真实 PLC / 产线</li><li><strong>前端只有列表页</strong>：缺产线看板、工单甘特图与异常预警视图</li></ul><h2 id="验证证据" tabindex="-1">验证证据 <a class="header-anchor" href="#验证证据" aria-label="Permalink to “验证证据”">​</a></h2><ul><li>业务闭环：<code>create → start → report(写生产记录) → qc(pass) → complete</code>，HTTP E2E 全链路通过</li><li>反向校验：<code>COMPLETED -&gt; CANCELLED</code> 被拦截，返回 <code>ILLEGAL_TRANSITION</code></li><li>复用边界：母仓 <code>openbiz_mes_*</code> 表（物料 / BOM / 工艺 / 生产工单 / 报工记录）+ <code>openbiz-saas-core</code>；业务层自建工单、报工 Mapper / Service / Controller 与状态机</li><li>实证记录：<a href="/my-vitepress-site/apps/openbiz/mes.html">OpenBiz 试水 › MES 生产执行</a></li><li>工程位置：<code>E:/8.cangku/for-job/openbiz-mes-app</code>（含 README 与 E2E 脚本）</li></ul><hr><p>上一级：<a href="/my-vitepress-site/instances/industrial/">02 工业数字化应用</a> · <a href="/my-vitepress-site/instances/">实例总览</a></p>',10)])])}const m=e(r,[["render",i]]);export{E as __pageData,m as default};
